`{ id: 'lawn-fertilizer', name: 'Lawn Fertilizer Calculator', desc: 'Product weight to hit a nitrogen rate', kw: 'lawn fertilizer calculator nitrogen rate lb per 1000 sq ft product', inputs: [{id:'area',label:'Lawn Area (sq ft)',type:'number',def:5000},{id:'rate',label:'Nitrogen Rate (lb per 1000 sq ft)',type:'number',def:1},{id:'npct',label:'Product N % (e.g. 29 for 29-0-4)',type:'number',def:29}], calc: function(v){ if(v.area<=0||v.npct<=0) return{result:'Enter positive values',chart:'',extra:''}; var nLb=v.area/1000*v.rate; var product=nLb/(v.npct/100); return{result:'Product: '+product.toFixed(1)+' lb',chart:Charts.bar([nLb,product-nLb],['Pure N','Filler']),extra:'Pure nitrogen needed: '+nLb.toFixed(2)+' lb | Calibrate the spreader — half-speed in two perpendicular passes beats one fast pass for even colour'};}, steps: function(v){ var nLb=v.area/1000*v.rate; var product=nLb/(v.npct/100); return['Step 1: N needed = '+v.area+' ÷ 1000 × '+v.rate+' = '+nLb.toFixed(2)+' lb N','Step 2: Product = N ÷ N% = '+nLb.toFixed(2)+' ÷ '+(v.npct/100)+' = '+product.toFixed(1)+' lb','Soluble N feeds fast for 4-6 weeks; slow-release stretches the same rate over 8-10'];} }`,
`{ id: 'candle-wax', name: 'Candle Wax Calculator', desc: 'Wax weight for a batch of container candles', kw: 'candle wax calculator container ounces batch soy', inputs: [{id:'jars',label:'Number of Jars',type:'number',def:12},{id:'oz',label:'Jar Size (oz)',type:'number',def:8}], calc: function(v){ if(v.jars<=0||v.oz<=0) return{result:'Enter positive values',chart:'',extra:''}; var wax=v.jars*v.oz*0.86; return{result:'Wax: '+wax.toFixed(1)+' oz',chart:Charts.bar([wax],['wax oz']),extra:'Fill containers to about 85-90% — wax is ~86% the density of water | Fragrance load 6-10% is by wax weight, add it on top'};}, steps: function(v){ var wax=v.jars*v.oz*0.86; return['Step 1: Total container volume = '+v.jars+' × '+v.oz+' oz = '+(v.jars*v.oz),'Step 2: × 0.86 (wax density vs water) = '+wax.toFixed(1)+' oz wax','Melt point and pour temp differ by wax type — soy around 85 °C melt, pour near 70-80 °C'];} }`,
`{ id: 'knit-gauge', name: 'Knitting Cast-On Calculator', desc: 'Stitches to cast on from gauge and width', kw: 'knitting cast on calculator gauge stitches per inch width', inputs: [{id:'width',label:'Finished Width (inches)',type:'number',def:20},{id:'spi',label:'Gauge (stitches per inch)',type:'number',def:5}], calc: function(v){ if(v.width<=0||v.spi<=0) return{result:'Enter positive values',chart:'',extra:''}; var st=Math.round(v.width*v.spi); return{result:'Cast on '+st+' stitches',chart:Charts.bar([st],['stitches']),extra:'Always knit a 4-inch swatch and wash it — gauge lies until blocked | Add 2 edge stitches if your pattern does not include selvedges'};}, steps: function(v){ var st=Math.round(v.width*v.spi); return['Formula: Stitches = width × gauge','Step 1: '+v.width+' in × '+v.spi+' sts/in = '+st+' stitches','Re-measure gauge mid-project — tension drifts with mood and yarn batch'];} }`,
`{ id: 'quilt-fabric', name: 'Quilt Backing Calculator', desc: 'Yardage for a quilt backing with seams', kw: 'quilt backing calculator yardage fabric width seam allowance', inputs: [{id:'w',label:'Quilt Width (inches)',type:'number',def:60},{id:'h',label:'Quilt Height (inches)',type:'number',def:80},{id:'fw',label:'Fabric Width (inches)',type:'number',def:42}], calc: function(v){ if(Math.min(v.w,v.h,v.fw)<=0) return{result:'Enter positive values',chart:'',extra:''}; var needW=v.w+8, needH=v.h+8; var panels=Math.ceil(needW/(v.fw-1)); var len=panels*needH/36; return{result:len.toFixed(2)+' yards',chart:Charts.bar([panels],['panels']),extra:'Backing should overhang 4 inches per side | Join panels with a 1/2 inch seam, pressed open, and remove the selvedges first'};}, steps: function(v){ var needW=v.w+8, needH=v.h+8; var panels=Math.ceil(needW/(v.fw-1)); var len=panels*needH/36; return['Step 1: Backing size = '+(v.w+8)+' × '+(v.h+8)+' in (4 in overhang each side)','Step 2: Panels across = ceil('+needW+' ÷ '+(v.fw-1)+') = '+panels,'Step 3: Length = '+panels+' × '+needH+' in ÷ 36 = '+len.toFixed(2)+' yards'];} }`
