`{ id: 'timesheet-hours', name: 'Timesheet Decimal Converter', desc: 'Convert hh:mm entries to decimal hours', kw: 'timesheet decimal hours calculator hh mm payroll convert', inputs: [{id:'times',label:'Time entries (comma separated hh:mm)',type:'text',def:'8:30,7:45,8:00'}], calc: function(v){ var parts=v.times.split(',').map(function(s){var m=s.trim().match(/^(\\d+):(\\d+)$/); return m?+m[1]+ +m[2]/60:NaN;}); if(parts.some(isNaN)) return{result:'Use hh:mm format, e.g. 8:30,7:45',chart:'',extra:''}; var tot=parts.reduce(function(a,b){return a+b;},0); return{result:'Total: '+tot.toFixed(2)+' hours',chart:Charts.bar(parts,parts.map(function(_,i){return 'D'+(i+1);})),extra:'Payroll wants decimals: 8:30 becomes 8.5, never 8.30 — that 0.30 reads as 18 minutes and shortchecks your pay'};}, steps: function(v){ var parts=v.times.split(',').map(function(s){var m=s.trim().match(/^(\\d+):(\\d+)$/); return m?+m[1]+ +m[2]/60:NaN;}); var tot=parts.reduce(function(a,b){return a+b;},0); return['Step 1: Convert each: '+parts.map(function(p){return p.toFixed(2);}).join(' + '),'Step 2: Sum = '+tot.toFixed(2)+' decimal hours','Minutes ÷ 60 is the whole trick: 15 min = 0.25, 45 min = 0.75'];} }`,
`{ id: 'overtime-rate', name: 'Overtime Pay Calculator', desc: 'Pay at time-and-a-half or double time', kw: 'overtime pay calculator time and a half double time hourly', inputs: [{id:'rate',label:'Base Hourly Rate ($)',type:'number',def:20},{id:'hours',label:'Overtime Hours',type:'number',def:10},{id:'mult',label:'Multiplier (1.5 or 2)',type:'number',def:1.5}], calc: function(v){ if(v.rate<=0||v.hours<0) return{result:'Enter valid values',chart:'',extra:''}; var pay=v.rate*v.mult*v.hours; return{result:'Overtime Pay: $'+pay.toFixed(2),chart:Charts.bar([v.rate*v.hours,pay-v.rate*v.hours],['Base value','Premium']),extra:'OT rate: $'+(v.rate*v.mult).toFixed(2)+'/h | US FLSA requires 1.5x past 40 h/week for non-exempt workers — some states add daily rules'};}, steps: function(v){ var pay=v.rate*v.mult*v.hours; return['Formula: pay = rate × multiplier × hours','Step 1: '+v.rate+' × '+v.mult+' = $'+(v.rate*v.mult).toFixed(2)+'/h OT rate','Step 2: × '+v.hours+' h = $'+pay.toFixed(2),'Salaried non-exempt workers earn OT too — the regular rate includes nondiscretionary bonuses'];} }`,
`{ id: 'shift-differential', name: 'Shift Differential Calculator', desc: 'Premium pay for nights or weekends', kw: 'shift differential calculator night shift premium weekend pay', inputs: [{id:'base',label:'Base Rate ($/h)',type:'number',def:25},{id:'diff',label:'Differential (%)',type:'number',def:15},{id:'hours',label:'Differential Hours',type:'number',def:8}], calc: function(v){ if(v.base<=0||v.diff<0||v.hours<0) return{result:'Enter valid values',chart:'',extra:''}; var rate=v.base*(1+v.diff/100); var extra=rate-v.base; return{result:'Premium Rate: $'+rate.toFixed(2)+'/h',chart:Charts.bar([v.base*v.hours,extra*v.hours],['Base pay','Differential']),extra:'Per shift: +$'+(extra*v.hours).toFixed(2)+' | Over a year of 160 night shifts, a 15% differential adds '+(extra*v.hours*160).toFixed(0)+' dollars — real money worth negotiating'};}, steps: function(v){ var rate=v.base*(1+v.diff/100); var extra=rate-v.base; return['Step 1: Premium rate = '+v.base+' × '+(1+v.diff/100)+' = $'+rate.toFixed(2)+'/h','Step 2: Uplift = $'+extra.toFixed(2)+'/h × '+v.hours+' h = $'+(extra*v.hours).toFixed(2)+' per shift','Differentials typically run 10-15% for nights, more for weekends or hazardous duty'];} }`
