`{ id: 'customer-ltv', name: 'Customer Lifetime Value Calculator', desc: 'Revenue per customer from ARPU, margin, and churn', kw: 'customer lifetime value calculator ltv arpu churn margin saas', inputs: [{id:'arpu',label:'Monthly Revenue per Customer ($)',type:'number',def:50},{id:'margin',label:'Gross Margin (%)',type:'number',def:70},{id:'churn',label:'Monthly Churn (%)',type:'number',def:5}], calc: function(v){ if(v.arpu<=0||v.churn<=0) return{result:'Revenue and churn must be positive',chart:'',extra:''}; var ltv=v.arpu*(v.margin/100)/(v.churn/100); var life=1/(v.churn/100); return{result:'LTV: $'+ltv.toFixed(0),chart:Charts.bar([ltv,v.arpu*(1-v.margin/100)/(v.churn/100)],['Gross LTV','Cost portion']),extra:'Average lifetime: '+life.toFixed(1)+' months | Compare with CAC — a healthy SaaS keeps LTV:CAC above 3:1'};}, steps: function(v){ var ltv=v.arpu*(v.margin/100)/(v.churn/100); return['Formula: LTV = ARPU × margin ÷ churn','Step 1: Gross profit per month = '+v.arpu+' × '+(v.margin/100)+' = $'+(v.arpu*v.margin/100).toFixed(2),'Step 2: ÷ churn '+(v.churn/100)+' = $'+ltv.toFixed(0)+' lifetime gross profit','Churn compounds: cutting it from 5% to 4% lifts lifetime from 20 to 25 months'];} }`,
`{ id: 'csat-score', name: 'CSAT Score Calculator', desc: 'Customer satisfaction percent from survey counts', kw: 'csat calculator customer satisfaction score survey percent', inputs: [{id:'good',label:'Satisfied Responses (4-5)',type:'number',def:180},{id:'total',label:'Total Responses',type:'number',def:200}], calc: function(v){ if(v.total<=0||v.good<0||v.good>v.total) return{result:'Enter valid counts',chart:'',extra:''}; var csat=v.good/v.total*100; return{result:'CSAT: '+csat.toFixed(1)+'%',chart:Charts.gauge(csat,100),extra:'Only 4-5 ratings count as satisfied | CSAT measures the transaction, NPS measures the relationship — they move differently'};}, steps: function(v){ var csat=v.good/v.total*100; return['Formula: CSAT = satisfied ÷ total × 100','Step 1: '+v.good+' ÷ '+v.total+' = '+(v.good/v.total).toFixed(3),'Step 2: × 100 = '+csat.toFixed(1)+'%','Segment by channel — chat and phone CSAT usually diverge from email'];} }`,
`{ id: 'conversion-funnel', name: 'Conversion Funnel Calculator', desc: 'Step-to-step and overall conversion rates', kw: 'conversion funnel calculator step rate drop off marketing', inputs: [{id:'s1',label:'Visitors',type:'number',def:1000},{id:'s2',label:'Added to Cart',type:'number',def:300},{id:'s3',label:'Checked Out',type:'number',def:60}], calc: function(v){ if(v.s1<=0) return{result:'Enter a positive visitor count',chart:'',extra:''}; var r1=v.s2/v.s1*100, r2=v.s3/v.s2*100, overall=v.s3/v.s1*100; return{result:'Overall: '+overall.toFixed(1)+'%',chart:Charts.bar([v.s1,v.s2,v.s3],['Visit','Cart','Purchase']),extra:'Step rates: '+(r1).toFixed(0)+'% then '+(r2).toFixed(0)+'% | The biggest drop-off is your leverage — a relative gain there beats the same effort anywhere else'};}, steps: function(v){ var r1=v.s2/v.s1*100, r2=v.s3/v.s2*100; return['Step 1: Visit → Cart: '+v.s2+' ÷ '+v.s1+' = '+r1.toFixed(1)+'%','Step 2: Cart → Purchase: '+v.s3+' ÷ '+v.s2+' = '+r2.toFixed(1)+'%','Step 3: Overall = '+r1.toFixed(1)+'% × '+r2.toFixed(1)+'% ÷ 100 = '+(r1*r2/100).toFixed(1)+'%','Funnel stages multiply — small wins at each step compound'];} }`,
`{ id: 'ab-test-significance', name: 'A/B Test Significance Calculator', desc: 'Z-score for a two-variant conversion test', kw: 'ab test significance calculator z score conversion split test', inputs: [{id:'na',label:'Variant A Visitors',type:'number',def:1000},{id:'ca',label:'Variant A Conversions',type:'number',def:50},{id:'nb',label:'Variant B Visitors',type:'number',def:1000},{id:'cb',label:'Variant B Conversions',type:'number',def:65}], calc: function(v){ if(v.na<=0||v.nb<=0) return{result:'Visitor counts must be positive',chart:'',extra:''}; var p1=v.ca/v.na, p2=v.cb/v.nb; var p=(v.ca+v.cb)/(v.na+v.nb); var se=Math.sqrt(p*(1-p)*(1/v.na+1/v.nb)); if(se===0) return{result:'No variance — check your inputs',chart:'',extra:''}; var z=(p2-p1)/se; var sig=Math.abs(z)>=1.96?'significant at 95%':Math.abs(z)>=1.64?'significant at 90%':'not significant'; return{result:'z = '+z.toFixed(2)+' ('+sig+')',chart:Charts.bar([p1*100,p2*100],['A %','B %']),extra:'A converts '+(p1*100).toFixed(2)+'%, B '+(p2*100).toFixed(2)+'% | Stop tests at the planned sample size — peeking early inflates false positives'};}, steps: function(v){ var p1=v.ca/v.na, p2=v.cb/v.nb; var p=(v.ca+v.cb)/(v.na+v.nb); var se=Math.sqrt(p*(1-p)*(1/v.na+1/v.nb)); var z=(p2-p1)/se; return['Step 1: Rates — A: '+(p1*100).toFixed(2)+'%, B: '+(p2*100).toFixed(2)+'%','Step 2: Pooled p = '+(v.ca+v.cb)+' ÷ '+(v.na+v.nb)+' = '+p.toFixed(4),'Step 3: SE = √(p(1−p)(1/nA+1/nB)) = '+se.toFixed(5),'Step 4: z = (pB − pA) ÷ SE = '+z.toFixed(3)+' — |z| ≥ 1.96 means 95% confidence'];} }`,
`{ id: 'project-bid', name: 'Project Bid Calculator', desc: 'Bid price from cost, contingency, and margin', kw: 'project bid calculator price margin contingency contractor estimate', inputs: [{id:'cost',label:'Direct Cost ($)',type:'number',def:50000},{id:'cont',label:'Contingency (%)',type:'number',def:10},{id:'margin',label:'Profit Margin (%)',type:'number',def:20}], calc: function(v){ if(v.cost<=0) return{result:'Cost must be positive',chart:'',extra:''}; var withCont=v.cost*(1+v.cont/100); var bid=withCont/(1-v.margin/100); return{result:'Bid: $'+bid.toFixed(0),chart:Charts.bar([v.cost,withCont-v.cost,bid-withCont],['Cost','Contingency','Margin']),extra:'Margin on price, not cost: dividing by (1 − margin) is correct — multiplying cost by 1.2 underprices every job'};}, steps: function(v){ var withCont=v.cost*(1+v.cont/100); var bid=withCont/(1-v.margin/100); return['Step 1: Cost + contingency = $'+v.cost.toLocaleString()+' × '+(1+v.cont/100)+' = $'+withCont.toLocaleString(),'Step 2: Bid = $'+withCont.toLocaleString()+' ÷ (1 − '+(v.margin/100)+') = $'+bid.toLocaleString(),'The division matters: a 20% margin on price equals a 25% markup on cost'];} }`,
`{ id: 'retainer-value', name: 'Retainer Value Calculator', desc: 'Contract value with a term discount applied', kw: 'retainer value calculator monthly contract discount annual', inputs: [{id:'monthly',label:'Monthly Fee ($)',type:'number',def:5000},{id:'months',label:'Term (months)',type:'number',def:12},{id:'disc',label:'Prepay Discount (%)',type:'number',def:10}], calc: function(v){ if(v.monthly<=0||v.months<=0) return{result:'Enter positive values',chart:'',extra:''}; var gross=v.monthly*v.months; var net=gross*(1-v.disc/100); return{result:'Contract Value: $'+net.toFixed(0),chart:Charts.bar([gross,gross-net],['List','Discount']),extra:'Effective monthly: $'+(net/v.months).toFixed(0)+' | The discount buys cash flow and commitment — cap it below your financing cost plus churn risk'};}, steps: function(v){ var gross=v.monthly*v.months; var net=gross*(1-v.disc/100); return['Step 1: List value = $'+v.monthly+' × '+v.months+' = $'+gross.toLocaleString(),'Step 2: Apply '+v.disc+'% prepay discount → $'+net.toLocaleString(),'Discounts should be traded, not given: tie them to longer terms or upfront payment'];} }`
